using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Reflection;using System.Threading;using System.Windows.Forms;using Accessibility;using System.Runtime.InteropServices;using System.Web.Script.Serialization;
class MsaaProbe{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;static Form form;static int checks;static string root;static List<object>rows=new List<object>();static IAccessible input,branch;static object inputId,branchId;
 [DllImport("oleacc.dll")]static extern int AccessibleObjectFromWindow(IntPtr hwnd,uint objectID,ref Guid interfaceID,[MarshalAs(UnmanagedType.Interface)]out object accessible);
 [DllImport("oleacc.dll")]static extern int AccessibleChildren(IAccessible parent,int first,int count,[Out,MarshalAs(UnmanagedType.LPArray,SizeParamIndex=2)]object[] children,out int obtained);
 static object Call(object o,string name,params object[]a){Type t=o as Type??o.GetType();return t.GetMethods(F).First(m=>m.Name==name&&m.GetParameters().Length==a.Length).Invoke(o is Type?null:o,a);}
 static void Check(bool b,string s){checks++;Console.WriteLine((b?"PASS ":"FAIL ")+s);if(!b)throw new Exception(s);}
 static void Pump(int ms=100){var end=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(2);}while(DateTime.UtcNow<end);}
 static void ActionClient(Action action){Exception error=null;var thread=new Thread(()=>{try{action();}catch(Exception ex){error=ex;}}){IsBackground=true};thread.SetApartmentState(ApartmentState.MTA);thread.Start();var deadline=DateTime.UtcNow.AddSeconds(20);while(thread.IsAlive&&DateTime.UtcNow<deadline)Pump(20);Check(!thread.IsAlive,"MSAA action returns without blocking the app");if(error!=null)throw error;Pump(200);}
 [STAThread]static int Main(string[]args){root=args[1];Directory.CreateDirectory(root);try{Application.EnableVisualStyles();var app=Assembly.LoadFile(Path.GetFullPath(args[0]));Call(app.GetType("Frociart.UiMotion"),"SetEnabled",false);form=(Form)Activator.CreateInstance(app.GetType("Frociart.MainForm"),F,null,new object[]{null,true},null);form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=Point.Empty;form.Show();Pump(700);Call(form,"SetDocument",Call(app.GetType("Frociart.Examples"),"Parity"),null,false);Call(form,"EnterEditor");Pump(400);var canvas=(Control)form.GetType().GetField("Canvas",F).GetValue(form);Check(canvas.Visible,"Production canvas is visible");var handle=canvas.Handle;Exception error=null;var thread=new Thread(()=>{try{Guid iid=typeof(IAccessible).GUID;object native;int hr=AccessibleObjectFromWindow(handle,0xFFFFFFFC,ref iid,out native);Check(hr==0&&native is IAccessible,"oleacc returns the real canvas IAccessible provider");var acc=(IAccessible)native;int count=acc.accChildCount;Check(count==12,"Native MSAA provider enumerates six blocks and six links");var children=new object[count];int got;hr=AccessibleChildren(acc,0,count,children,out got);Check(hr>=0&&got==count,"AccessibleChildren retrieves all virtual graph children");foreach(var child in children){IAccessible node=child as IAccessible;object id=node==null?child:0;node=node??acc;string name=node.get_accName(id),value=node.get_accValue(id),description=node.get_accDescription(id),action=node.get_accDefaultAction(id);object role=node.get_accRole(id),state=node.get_accState(id);rows.Add(new{name=name,value=value,description=description,action=action,role=role,state=state});if(name.StartsWith("Input:")){input=node;inputId=id;}if(name.StartsWith("Collegamento · No")){branch=node;branchId=id;}}Check(rows.Count==12,"All graph child details cross the native MSAA boundary");}catch(Exception e){error=e;}}){IsBackground=true};thread.SetApartmentState(ApartmentState.MTA);thread.Start();var deadline=DateTime.UtcNow.AddSeconds(45);while(thread.IsAlive&&DateTime.UtcNow<deadline)Pump(20);Check(!thread.IsAlive,"MSAA client terminates without freezing the app");if(error!=null)throw error;
 Check(input!=null&&branch!=null,"Native enumeration identifies input and No branch by semantic name");ActionClient(()=>input.accSelect(3,inputId));Check(canvas.AccessibilityObject.GetSelected().Name.StartsWith("Input:"),"Native accSelect reaches the actual input block");ActionClient(()=>{int state=Convert.ToInt32(input.get_accState(inputId));Check((state&(int)AccessibleStates.Selected)!=0,"MSAA state reflects the actual selected input");});ActionClient(()=>branch.accDoDefaultAction(branchId));Check(canvas.AccessibilityObject.GetSelected().Name.Contains("Dispari"),"Native branch default action reaches its actual destination");
 File.WriteAllText(Path.Combine(root,"msaa.json"),new JavaScriptSerializer().Serialize(new{status="PASS_NATIVE_MSAA_NOT_AUDIO",checks=checks,rows=rows}));Call(form,"SetDocument",Call(app.GetType("Frociart.DiagramIO"),"CreateBlank"),null,false);form.Close();Console.WriteLine("MSAA_PROBE PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);File.WriteAllText(Path.Combine(root,"msaa-failure.txt"),e.ToString());return 1;}finally{if(form!=null&&!form.IsDisposed)form.Dispose();}}
}
